import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv_transpose_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int h_in, int w_in, int h_out, int w_out,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int groups,
    int total_elements
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= total_elements) return;

    int n = tid / (out_channels * h_out * w_out);
    int remainder = tid % (out_channels * h_out * w_out);
    int c_out = remainder / (h_out * w_out);
    remainder %= (h_out * w_out);
    int h = remainder / w_out;
    int w = remainder % w_out;

    int g = c_out / (out_channels / groups);
    int in_channels_per_group = in_channels / groups;
    int c_in_start = g * in_channels_per_group;

    float sum = 0.0f;

    for (int kh = 0; kh < kernel_h; ++kh) {
        for (int kw = 0; kw < kernel_w; ++kw) {
            int i_plus_pad = h + padding_h - kh * dilation_h;
            int j_plus_pad = w + padding_w - kw * dilation_w;

            if (i_plus_pad < 0 || i_plus_pad % stride_h != 0) continue;
            if (j_plus_pad < 0 || j_plus_pad % stride_w != 0) continue;

            int i = i_plus_pad / stride_h;
            int j = j_plus_pad / stride_w;

            if (i >= h_in || j >= w_in) continue;

            for (int c_in = 0; c_in < in_channels_per_group; ++c_in) {
                int input_idx = n * in_channels * h_in * w_in + (c_in_start + c_in) * h_in * w_in + i * w_in + j;
                int weight_idx = c_out * (in_channels_per_group * kernel_h * kernel_w) + c_in * kernel_h * kernel_w + kh * kernel_w + kw;

                sum += input[input_idx] * weight[weight_idx];
            }
        }
    }

    if (bias != nullptr) {
        sum += bias[c_out];
    }

    output[tid] = sum;
}

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input, torch::Tensor weight, torch::optional<torch::Tensor> bias,
    torch::IntArrayRef stride, torch::IntArrayRef padding,
    torch::IntArrayRef dilation, int groups
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int h_in = input.size(2);
    int w_in = input.size(3);

    int out_channels = weight.size(0);
    int kernel_h = weight.size(2);
    int kernel_w = weight.size(3);

    int stride_h = stride[0], stride_w = stride[1];
    int padding_h = padding[0], padding_w = padding[1];
    int dilation_h = dilation[0], dilation_w = dilation[1];

    int h_out = (h_in - 1) * stride_h - 2 * padding_h + dilation_h * (kernel_h - 1) + 1;
    int w_out = (w_in - 1) * stride_w - 2 * padding_w + dilation_w * (kernel_w - 1) + 1;

    auto output = torch::zeros({batch_size, out_channels, h_out, w_out}, input.options());

    int total_elements = output.numel();
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    const float* input_ptr = input.data_ptr<float>();
    const float* weight_ptr = weight.data_ptr<float>();
    const float* bias_ptr = bias ? bias->data_ptr<float>() : nullptr;
    float* output_ptr = output.data_ptr<float>();

    conv_transpose2d_kernel<<<num_blocks, block_size>>>(
        input_ptr, weight_ptr, bias_ptr, output_ptr,
        batch_size, in_channels, out_channels,
        h_in, w_in, h_out, w_out,
        kernel_h, kernel_w,
        stride_h, stride_w,
        padding_h, padding_w,
        dilation_h, dilation_w,
        groups,
        total_elements
    );

    return output;
}
"""

conv_transpose_cpp_source = """
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input, torch::Tensor weight, torch::optional<torch::Tensor> bias,
    torch::IntArrayRef stride, torch::IntArrayRef padding,
    torch::IntArrayRef dilation, int groups
);
"""

conv_transpose2d = load_inline(
    name='conv_transpose2d',
    cpp_sources=conv_transpose_cpp_source,
    cuda_sources=conv_transpose_source,
    functions=['conv_transpose2d_cuda'],
    verbose=True,
    extra_cuda_cflags=['-O3']
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        self.weight = nn.Parameter(torch.Tensor(
            out_channels,
            in_channels // groups,
            kernel_size[0],
            kernel_size[1]
        ))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose2d.conv_transpose2d_cuda(
            x, self.weight, self.bias,
            self.stride, self.padding, self.dilation, self.groups
        )
